mkdir -p ~/development/.tmp/stallion-grey && cat > ~/development/.tmp/stallion-grey/probe.mjs <<'EOF'
import { spawn } from "node:child_process";
import { writeFileSync, mkdtempSync } from "node:fs";
const [url, out] = process.argv.slice(2);
const dir = mkdtempSync(process.env.HOME + "/development/.tmp/stallion-grey/prof-");
const chrome = spawn("/usr/bin/google-chrome", ["--headless=new", "--remote-debugging-port=9333", `--user-data-dir=${dir}`, "--no-first-run", "--window-size=1280,800", "about:blank"], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let ver;
for (let i = 0; i < 50; i++) { try { ver = await (await fetch("http://127.0.0.1:9333/json/list")).json(); break; } catch { await sleep(200); } }
const page = ver.find((p) => p.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const pending = new Map(); const log = [];
ws.addEventListener("message", (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); return; }
  if (m.method === "Runtime.consoleAPICalled") log.push(`console.${m.params.type}: ${m.params.args.map((a) => a.value ?? a.description).join(" ")}`);
  if (m.method === "Runtime.exceptionThrown") log.push(`exception: ${m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text}`);
  if (m.method === "Log.entryAdded") log.push(`log.${m.params.entry.level}: ${m.params.entry.text} ${m.params.entry.url ?? ""}`);
  if (m.method === "Network.loadingFailed") log.push(`netfail: ${m.params.errorText} ${m.params.requestId}`);
  if (m.method === "Network.responseReceived" && m.params.response.status >= 400) log.push(`http ${m.params.response.status} ${m.params.response.url}`);
  if (m.method === "Network.webSocketCreated") log.push(`ws: ${m.params.url}`);
  if (m.method === "Network.webSocketClosed") log.push(`ws closed`);
});
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
for (const d of ["Runtime", "Log", "Network", "Page"]) await send(`${d}.enable`);
await send("Page.navigate", { url });
await sleep(6000);
const ev = await send("Runtime.evaluate", { expression: "JSON.stringify({secure: isSecureContext, uuid: typeof crypto.randomUUID, app: document.getElementById('app')?.innerHTML.slice(0,600)})", returnByValue: true });
log.push("state: " + ev.result?.result?.value);
const shot = await send("Page.captureScreenshot", { format: "png" });
writeFileSync(out, Buffer.from(shot.result.data, "base64"));
console.log(log.join("\n"));
ws.close(); chrome.kill();
EOF
cd ~/development/.tmp/stallion-grey && timeout 60 node probe.mjs http://100.104.44.51:5173/b/default before-tailnet.png; echo ---; timeout 60 node probe.mjs http://127.0.0.1:5173/b/default before-localhost.png

