content.content:
:root {
  --paper: #fbfaf7;
  --panel: #ffffffee;
  --ink: #1f2328;
  --line: #d9d6cf;
  --accent: #0090ff;
  color-scheme: light;
}

html,
body,
#app {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

.board {
  position: fixed;
  inset: 0;
import { type BoardStore, openBoardStore, type StoredObject } from "@stallion/client-store";
import { type Point, type Tile, tileBounds, viewTiles } from "@stallion/geometry";
import type { PencilSize, Stroke } from "@stallion/schema";
import {
  type Camera,
  pan,
  pinch,
  screenToWorld,
  viewBounds,
  wheelFactor,
  worldToScreen,
  zoomAt,
} from "./camera";
import { isVisible } from "./culling";
import { createGestures, type Effect, type PointerKind } from "./gesture";
import {
